      "type": "float",
      "initial_value": 24,
      "source_fact_id": "do_dai_ef"
    },
    {
      "name": "G",
      "type": "point3",
      "source_fact_id": "g_tren_day_e"
    },
    {
      "name": "H",
      "type": "point3",
      "source_fact_id": "h_tren_ef"
    },
    {
      "name": "do_dai_eh",
      "type": "float",
      "initial_value": 6,
      "source_fact_id": "do_dai_eh"
    },
    {
