    },
    {
      "name": "gamma",
      "type": "section",
      "source_fact_id": "cat_hinh_tru_theo_gamma"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "E",
      "at": [0, 0, 0],
      "label": "Tâm đáy dưới của hình trụ"
    },
    {
      "kind": "declare_point",
      "target_var": "F",
      "at": [0, 0, 24],
      "label": "Tâm đáy trên của hình trụ"
    },
    {
      "kind": "declare_point",
      "target_var": "G",
      "at": [7, 0, 0],
      "model_assumption": "Đặt G tại (7,0,0) trên đường tròn đáy tâm E",
      "label": "Điểm G trên đường tròn đáy tâm E"
    },
    {
      "kind": "declare_point",
      "target_var": "H",
      "at": [0, 0, 6],
      "model_assumption": "Đặt H tại (0,0,6) trên đoạn EF sao cho EH=6",
      "label": "Điểm H trên đoạn EF"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "hinh_tru",
      "curved_kind": "cylinder",
      "anchor": "E",
      "apex_or_top": "F",
      "rim_point": "G",
      "label": "Hình trụ có trục EF, bán kính đáy 7"
    },
    {
      "kind": "construct_line",
      "target_var": "truc_ef",
      "through_a": "E",
      "through_b": "F",
      "label": "Trục của hình trụ"
    },
    {
      "kind": "assign",
      "target_var": "mp_gamma",
      "expr": {
        "kind": "plane_perpendicular_to_line",
        "point": "H",
        "line": "truc_ef"
      },
      "label": "Mặt phẳng đi qua H và vuông góc với trục EF"
    },
    {
      "kind": "construct_section",
      "target_var": "gamma",
      "solid": "hinh_tru",
      "plane": "mp_gamma",
      "label": "Đường tròn thiết diện (γ)"
    },
    {
      "kind": "assign",
      "target_var": "ban_kinh_gamma",
      "expr": {
        "kind": "measure",
        "quantity": "radius",
        "of": "gamma"
      },
      "label": "Bán kính của đường tròn (γ)"
    }
  ],
  "pedagogical_intent": "Chương trình này minh họa rằng một mặt phẳng cắt hình trụ vuông góc với trục của nó sẽ tạo ra một thiết diện là đường tròn có bán kính bằng bán kính đáy của hình trụ, bất kể vị trí của mặt phẳng trên trục."
}

