{
  "title": "Tính bán kính đường tròn thiết diện của hình nón",
  "description": "Chương trình dựng hình nón, mặt phẳng cắt vuông góc với trục, và tính bán kính đường tròn thiết diện.",
  "memory_declarations": [
    {
      "name": "D",
      "type": "point3",
      "source_fact_id": "cone_apex"
    },
    {
      "name": "T",
      "type": "point3",
      "source_fact_id": "cone_base_center"
    },
    {
      "name": "U",
      "type": "point3",
      "source_fact_id": "point_u_on_base_circle"
    },
    {
      "name": "ban_kinh_day",
      "type": "float",
      "initial_value": "15",
      "source_fact_id": "base_radius"
    },
    {
      "name": "chieu_cao_dt",
      "type": "float",
      "initial_value": "20",
      "source_fact_id": "cone_height"
    },
    {
      "name": "do_dai_dv",
      "type": "float",
      "initial_value": "8",
      "source_fact_id": "dv_length"
    },
    {
      "name": "sigma",
      "type": "section",
      "source_fact_id": "section_is_circle_sigma"
    },
    {
      "name": "ban_kinh_sigma",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "T",
      "at": [0, 0, 0],
      "label": "Tâm đáy hình nón"
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [0, 0, 20],
      "label": "Đỉnh hình nón"
    },
    {
      "kind": "declare_point",
      "target_var": "U",
      "at": [15, 0, 0],
      "label": "Điểm trên đường tròn đáy"
    },
    {
      "kind": "construct_curved_solid",
      "target_var": "hinh_non",
      "curved_kind": "cone",
      "anchor": "T",
      "apex_or_top": "D",
      "rim_point": "U",
      "label": "Hình nón"
    },
    {
      "kind": "construct_point",
      "target_var": "V",
      "expr": {
        "kind": "divide_segment",
        "a": "D",
        "b": "T",
        "ratio": {
          "kind": "arith",
          "op": "//",
          "left": { "kind": "var", "name": "do_dai_dv" },
          "right": { "kind": "var", "name": "chieu_cao_dt" }
        }
      },
      "label": "Điểm V trên trục DT"
    },
    {
      "kind": "construct_line",
      "target_var": "truc_dt",
      "through_a": "D",
      "through_b": "T",
      "label": "Trục hình nón DT"
    },
    {
      "kind": "assign",
      "target_var": "mat_phang_cat",
      "expr": {
        "kind": "plane_perpendicular_to_line",
        "point": "V",
        "line": "truc_dt"
      },
      "source_fact_id": "plane_perp_axis",
      "label": "Mặt phẳng vuông góc với trục DT tại V"
    },
    {
      "kind": "construct_section",
      "target_var": "sigma",
      "solid": "hinh_non",
      "plane": "mat_phang_cat",
      "label": "Đường tròn thiết diện (σ)"
    },
    {
      "kind": "assign",
      "target_var": "ban_kinh_sigma",
      "expr": {
        "kind": "measure",
        "quantity": "radius",
        "of": "sigma"
      },
      "label": "Bán kính của (σ)"
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách dựng hình nón, mặt phẳng cắt vuông góc với trục, và tính bán kính của thiết diện tròn bằng cách sử dụng tỉ lệ đồng dạng trong hình học không gian."
}

